package dev.konqasasas.beat.domain.endurance;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class EnduranceSessionTest {@Test void skippedProgressActivatesZonesAndGoal(){UUID id=UUID.randomUUID();var s=new EnduranceSession(Map.of(id,"P"),new EnduranceRules(3,6,9));s.activate(id);var u=s.reach(id,9,100);assertTrue(u.zone2());assertTrue(u.zone3());assertTrue(u.goal());assertEquals(9,s.record(id).maxProgress());}@Test void zoneCutoffFreezesPlayersBelowZone(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var s=new EnduranceSession(Map.of(a,"A",b,"B"),new EnduranceRules(3,6,9));s.activate(a);s.activate(b);s.reach(a,3,10);assertEquals(b,s.eliminateWithoutZone(2).getFirst().id());assertFalse(s.active(b));}}
